import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import '../../../core/theme/app_theme.dart';import '../../../core/widgets/primary_button.dart';import '../../bloc/onboarding_cubit.dart';import 'onboarding_widgets.dart';
class LoadScreen extends StatelessWidget{const LoadScreen({super.key});Widget build(BuildContext c)=>OnboardingFrame(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const StepHeader(step:1),const Text('Сколько времени вы готовы\nуделять?',style:TextStyle(fontSize:21,fontWeight:FontWeight.w800,color:AppColors.text)),const SizedBox(height:10),const Text('Выберите комфортную длительность\nежедневной практики.'),const SizedBox(height:24),BlocBuilder<OnboardingCubit,OnboardingState>(builder:(c,s)=>Column(children:[Row(mainAxisAlignment:MainAxisAlignment.spaceAround,children:[5,15,30].map((m)=>ChoiceChip(label:Text(m.toString()+' мин'),selected:s.minutes==m,onSelected:(_)=>c.read<OnboardingCubit>().setMinutes(m))).toList()),Slider(value:s.minutes.toDouble(),min:5,max:30,divisions:5,onChanged:(v)=>c.read<OnboardingCubit>().setMinutes(v.round())),Container(width:double.infinity,padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:AppColors.mint,borderRadius:BorderRadius.circular(14)),child:Text(s.minutes.toString()+' минут в день — это\n+'+(s.minutes*365/60).round().toString()+' ч полезных действий\nв год!',style:const TextStyle(color:AppColors.primaryDark,fontWeight:FontWeight.w800))),const SizedBox(height:25),PrimaryButton(label:'Сформировать мой план',onPressed:()=>c.read<OnboardingCubit>().next())]))]));}
